"""HTTP entry point for StreamMill."""

from __future__ import annotations

import argparse
import json
import math
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlsplit

from .service import (
    EventIdConflictError,
    Service,
    StreamExistsError,
    StreamNotFoundError,
